const item = $input.item.json;
const output = String(item.output || '').trim();
const intermediateSteps = Array.isArray(item.intermediateSteps) ? item.intermediateSteps : [];

// chatId depuis Telegram Trigger - toujours fiable
let chatId = '';
try { chatId = $('Telegram Trigger').item.json.message.chat.id.toString(); } catch(e) {}

// Stratégie 1: parser les appels d'outils de l'agent (intermediateSteps)
let imageUrl = null;
for (const step of intermediateSteps) {
  const obs = step.observation;
  if (!obs) continue;
  try {
    const parsed = typeof obs === 'string' ? JSON.parse(obs) : obs;
    if (parsed && parsed.data && Array.isArray(parsed.data) && parsed.data[0] && parsed.data[0].url) {
      imageUrl = parsed.data[0].url;
      break;
    }
  } catch(e) {
    const m = String(obs).match(/https?:\/\/oaidalleapiprodscus\.blob\.core\.windows\.net\/[^\s"'\)\]]+/);
    if (m) { imageUrl = m[0]; break; }
  }
}

// Stratégie 2: fallback regex sur le texte de réponse
if (!imageUrl) {
  const m1 = output.match(/https?:\/\/oaidalleapiprodscus\.blob\.core\.windows\.net\/[^\s<>"'\)\]]+/i);
  if (m1) imageUrl = m1[0];
  else {
    const m2 = output.match(/https?:\/\/[^\s<>"'\)\]]+\.(?:png|jpg|jpeg|gif|webp)(?:[?#][^\s<>"'\)\]]*)?/i);
    if (m2) imageUrl = m2[0];
  }
}

// Légende = texte sans URLs
let caption = output
  .replace(/https?:\/\/oaidalleapiprodscus\.blob\.core\.windows\.net\/[^\s<>"'\)\]]+/gi, '')
  .replace(/https?:\/\/[^\s<>"'\)\]]+\.(?:png|jpg|jpeg|gif|webp)(?:[?#][^\s<>"'\)\]]*)?/gi, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

if (!caption || caption.length < 2) caption = imageUrl ? '\uD83C\uDFA8 Image g\u00e9n\u00e9r\u00e9e' : '';
if (caption.length > 1024) caption = caption.substring(0, 1021) + '...';

// Texte final jamais vide
let finalText = output;
if (!finalText) finalText = 'D\u00e9sol\u00e9, aucune r\u00e9ponse g\u00e9n\u00e9r\u00e9e.';
if (finalText.length > 4096) finalText = finalText.substring(0, 4093) + '...';

return [{ json: { output: finalText, imageUrl, hasImage: Boolean(imageUrl && chatId), caption, chatId } }];
